1	import "server-only";
2	import { createPublicKey, verify as cryptoVerify } from "node:crypto";
3	import { getSetting, getSettingBool } from "./settings";
4	import { decryptSecret } from "./crypto-box";
5	
6	/**
7	 * Thin Discord REST + Interactions-verification layer for the Nxeon support
8	 * bridge (lib/discord-bridge.ts). Deliberately NOT a discord.js Gateway
9	 * client and NOT a long-running process: this bot only ever (a) makes plain
10	 * REST calls the platform's own server code triggers, and (b) answers
11	 * Discord's HTTP "Interactions Endpoint" POSTs (button clicks, modal
12	 * submits) via app/api/webhooks/discord/route.ts. See the research this
13	 * build executed: an HTTP-only bot is the right shape for this codebase's
14	 * existing poll/request-response architecture, and Discord forum channels
15	 * cannot have private threads anyway (irrelevant here since the bridge uses
16	 * plain text channels — see lib/discord-bridge.ts for that call).
17	 *
18	 * Every config value is read via getSetting/getSettingBool/decryptSecret —
19	 * NEVER a bare process.env.DISCORD_* — except as a secondary fallback
20	 * mirroring the exact convention lib/kb-llm.ts's resolveBotKey() already
21	 * established for kb_bot_api_key.
22	 */
23	
24	const DISCORD_API_BASE = "https://discord.com/api/v10";
25	
26	// ---------------------------------------------------------------------------
27	// Config
28	// ---------------------------------------------------------------------------
29	
30	export async function discordEnabled(): Promise<boolean> {
31	  return getSettingBool("discord_enabled", false);
32	}
33	
34	export async function discordApplicationId(): Promise<string> {
35	  const v = (await getSetting("discord_application_id", "")).trim();
36	  return v || (process.env.DISCORD_APPLICATION_ID ?? "").trim();
37	}
38	
39	export async function discordGuildId(): Promise<string> {
40	  const v = (await getSetting("discord_guild_id", "")).trim();
41	  return v || (process.env.DISCORD_GUILD_ID ?? "").trim();
42	}
43	
44	export async function discordPublicKey(): Promise<string> {
45	  const v = (await getSetting("discord_public_key", "")).trim();
46	  return v || (process.env.DISCORD_PUBLIC_KEY ?? "").trim();
47	}
48	
49	/** Decrypt-on-read, mirroring lib/kb-llm.ts's resolveBotKey() exactly. */
50	export async function discordBotToken(): Promise<string | null> {
51	  const enc = await getSetting("discord_bot_token", "");
52	  const own = decryptSecret(enc || null);
53	  if (own && own.trim()) return own.trim();
54	  const platform = process.env.DISCORD_BOT_TOKEN;
55	  return platform && platform.trim() ? platform.trim() : null;
56	}
57	
58	/**
59	 * RETIRED — no longer read anywhere. See the doc comment on
60	 * `discord_reply_as_user_id` in lib/settings.ts for why: real per-Discord-user
61	 * identity linking (`User.discordUserId`) replaced this single-owner stand-in,
62	 * with no silent fallback. Left in place only so nothing that still imports it
63	 * (there should be nothing) breaks; do not add a new caller.
64	 */
65	export async function discordReplyAsUserId(): Promise<string> {
66	  return (await getSetting("discord_reply_as_user_id", "")).trim();
67	}
68	
69	/**
70	 * OAuth2 client secret for the staff Discord-account-linking flow (decrypt-on-
71	 * read, mirroring `discordBotToken()` above exactly). Used ONLY by
72	 * lib/discord-oauth.ts's token-exchange call — never logged, never sent to the
73	 * browser.
74	 */
75	export async function discordClientSecret(): Promise<string | null> {
76	  const enc = await getSetting("discord_client_secret", "");
77	  const own = decryptSecret(enc || null);
78	  return own && own.trim() ? own.trim() : null;
79	}
80	
81	// ---------------------------------------------------------------------------
82	// Ed25519 interaction-signature verification
83	// ---------------------------------------------------------------------------
84	
85	// The fixed 12-byte ASN.1 prefix for an Ed25519 SubjectPublicKeyInfo (SPKI)
86	// DER structure — "SEQUENCE { SEQUENCE { OID 1.3.101.112 } BIT STRING }".
87	// Discord (like most Ed25519 key issuers) hands out only the raw 32-byte
88	// public key as hex; Node's `crypto.createPublicKey` needs a full SPKI DER
89	// blob to build a KeyObject, and this prefix is constant for every Ed25519
90	// key, so prepending it to the raw 32 bytes reconstructs a valid SPKI DER
91	// value Node can parse. Verified against Node 22's `node:crypto` directly
92	// (generateKeyPairSync("ed25519") → export raw pub → reconstruct via this
93	// prefix → verify() succeeds and correctly rejects a tampered payload).
94	const ED25519_SPKI_DER_PREFIX = Buffer.from("302a300506032b6570032100", "hex");
95	
96	function ed25519PublicKeyFromHex(hex: string) {
97	  const raw = Buffer.from(hex, "hex");
98	  if (raw.length !== 32) throw new Error(`Discord public key must decode to 32 bytes, got ${raw.length}`);
99	  return createPublicKey({
100	    key: Buffer.concat([ED25519_SPKI_DER_PREFIX, raw]),
101	    format: "der",
102	    type: "spki",
103	  });
104	}
105	
106	/**
107	 * Verify a Discord Interactions Endpoint request. Discord signs
108	 * `timestamp + rawBody` with Ed25519 and sends the signature + timestamp as
109	 * headers; this MUST be checked against the raw (pre-JSON-parse) request body
110	 * before trusting anything in it. Returns false on ANY problem (missing
111	 * headers, malformed hex, wrong-length key, bad signature, tampered body) —
112	 * never throws, so callers can treat "false" as the single "reject with 401"
113	 * signal.
114	 */
115	export function verifyDiscordSignature(args: {
116	  rawBody: string;
117	  signature: string | null | undefined;
118	  timestamp: string | null | undefined;
119	  publicKeyHex: string;
120	}): boolean {
121	  const { rawBody, signature, timestamp, publicKeyHex } = args;
122	  if (!signature || !timestamp || !publicKeyHex) return false;
123	  try {
124	    if (!/^[0-9a-f]+$/i.test(signature) || !/^[0-9a-f]+$/i.test(publicKeyHex)) return false;
125	    const key = ed25519PublicKeyFromHex(publicKeyHex);
126	    const message = Buffer.from(timestamp + rawBody, "utf8");
127	    const sig = Buffer.from(signature, "hex");
128	    return cryptoVerify(null, message, key, sig);
129	  } catch {
130	    return false;
131	  }
132	}
133	
134	// ---------------------------------------------------------------------------
135	// REST client
136	// ---------------------------------------------------------------------------
137	
138	export class DiscordApiError extends Error {
139	  constructor(
140	    public status: number,
141	    public body: unknown,
142	  ) {
143	    super(`Discord API ${status}: ${typeof body === "string" ? body : JSON.stringify(body)}`);
144	  }
145	}
146	
147	/**
148	 * Bot-authenticated REST call. Respects a single 429 retry (Discord's rate
149	 * limits are generous at this volume — 50 req/s global — so anything beyond
150	 * one retry would indicate a real problem, not routine throttling). Returns
151	 * `null` (never throws) when the bot token isn't configured, so every caller
152	 * in lib/discord-bridge.ts can stay a best-effort no-op.
153	 */
154	export async function discordFetch(
155	  path: string,
156	  init: { method?: string; body?: unknown; retried?: boolean } = {},
157	): Promise<{ status: number; json: unknown } | null> {
158	  const token = await discordBotToken();
159	  if (!token) {
160	    console.error("[discord] no bot token configured — cannot call", path);
161	    return null;
162	  }
163	  const res = await fetch(`${DISCORD_API_BASE}${path}`, {
164	    method: init.method ?? "GET",
165	    headers: {
166	      Authorization: `Bot ${token}`,
167	      "Content-Type": "application/json",
168	    },
169	    body: init.body !== undefined ? JSON.stringify(init.body) : undefined,
170	  });
171	
172	  if (res.status === 429 && !init.retried) {
173	    const retryAfterSec = Number(res.headers.get("Retry-After") ?? "1") || 1;
174	    await new Promise((r) => setTimeout(r, Math.min(retryAfterSec, 5) * 1000));
175	    return discordFetch(path, { ...init, retried: true });
176	  }
177	
178	  const text = await res.text();
179	  let json: unknown = null;
180	  if (text) {
181	    try {
182	      json = JSON.parse(text);
183	    } catch {
184	      json = text;
185	    }
186	  }
187	  return { status: res.status, json };
188	}
189	
190	// ---------------------------------------------------------------------------
191	// Typed helpers
192	// ---------------------------------------------------------------------------
193	
194	/** Discord channel type 0 = GUILD_TEXT. */
195	const GUILD_TEXT_CHANNEL_TYPE = 0;
196	
197	export async function createGuildTextChannel(name: string, topic?: string): Promise<string | null> {
198	  const guildId = await discordGuildId();
199	  if (!guildId) {
200	    console.error("[discord] no guild id configured — cannot create channel");
201	    return null;
202	  }
203	  // Discord channel names: lowercase, hyphens, max 100 chars, no spaces.
204	  const safeName = name
205	    .toLowerCase()
206	    .replace(/[^a-z0-9-]+/g, "-")
207	    .replace(/-+/g, "-")
208	    .replace(/^-|-$/g, "")
209	    .slice(0, 90) || "ticket";
210	
211	  const res = await discordFetch(`/guilds/${guildId}/channels`, {
212	    method: "POST",
213	    body: {
214	      name: safeName,
215	      type: GUILD_TEXT_CHANNEL_TYPE,
216	      topic: topic?.slice(0, 1024),
217	    },
218	  });
219	  if (!res || res.status >= 300) {
220	    console.error("[discord] createGuildTextChannel failed", res?.status, res?.json);
221	    return null;
222	  }
223	  return (res.json as { id: string }).id;
224	}
225	
226	/** A button (type 2) inside a single action row (type 1), Reply style. */
227	function replyButtonRow(customId: string, label = "Reply"): unknown {
228	  return {
229	    type: 1,
230	    components: [{ type: 2, style: 1, label, custom_id: customId }],
231	  };
232	}
233	
234	/** Post a plain message, optionally with a Reply button. */
235	export async function postChannelMessage(
236	  channelId: string,
237	  content: string,
238	  opts: { replyButtonCustomId?: string } = {},
239	): Promise<boolean> {
240	  const res = await discordFetch(`/channels/${channelId}/messages`, {
241	    method: "POST",
242	    body: {
243	      content: content.slice(0, 2000), // Discord message content cap
244	      components: opts.replyButtonCustomId ? [replyButtonRow(opts.replyButtonCustomId)] : undefined,
245	    },
246	  });
247	  if (!res || res.status >= 300) {
248	    console.error("[discord] postChannelMessage failed", channelId, res?.status, res?.json);
249	    return false;
250	  }
251	  return true;
252	}
253	
254	/** Best-effort bot-authenticated lookup of a Discord user's public profile (for display only — e.g. showing a linked username in Settings). Returns null on ANY problem. */
255	export async function getDiscordUserById(userId: string): Promise<{ id: string; username: string } | null> {
256	  const res = await discordFetch(`/users/${userId}`);
257	  if (!res || res.status >= 300) return null;
258	  const json = res.json as { id?: unknown; username?: unknown };
259	  if (typeof json.id !== "string") return null;
260	  return { id: json.id, username: typeof json.username === "string" ? json.username : "" };
261	}
262	
263	export async function getChannel(channelId: string): Promise<{ id: string; name: string } | null> {
264	  const res = await discordFetch(`/channels/${channelId}`);
265	  if (!res || res.status >= 300) return null;
266	  return res.json as { id: string; name: string };
267	}
268	
269	export async function deleteChannel(channelId: string): Promise<boolean> {
270	  const res = await discordFetch(`/channels/${channelId}`, { method: "DELETE" });
271	  return Boolean(res && res.status < 300);
272	}
273	
274	// ---------------------------------------------------------------------------
275	// Interaction response helpers (used by app/api/webhooks/discord/route.ts)
276	// ---------------------------------------------------------------------------
277	
278	/** Interaction type constants (Discord API v10). */
279	export const InteractionType = {
280	  PING: 1,
281	  APPLICATION_COMMAND: 2,
282	  MESSAGE_COMPONENT: 3,
283	  APPLICATION_COMMAND_AUTOCOMPLETE: 4,
284	  MODAL_SUBMIT: 5,
285	} as const;
286	
287	/** Interaction callback type constants. */
288	export const InteractionCallbackType = {
289	  PONG: 1,
290	  CHANNEL_MESSAGE_WITH_SOURCE: 4,
291	  MODAL: 9,
292	} as const;
293	
294	/** Build the modal-open response body for a "Reply" button click. */
295	export function replyModalResponse(customId: string, title = "Reply to customer") {
296	  return {
297	    type: InteractionCallbackType.MODAL,
298	    data: {
299	      custom_id: customId,
300	      title,
301	      components: [
302	        {
303	          type: 1,
304	          components: [
305	            {
306	              type: 4, // TEXT_INPUT
307	              custom_id: "reply_text",
308	              style: 2, // paragraph
309	              label: "Your reply",
310	              required: true,
311	              max_length: 4000,
312	            },
313	          ],
314	        },
315	      ],
316	    },
317	  };
318	}
319	
320	/** Build a simple, visible channel-message acknowledgement response body. */
321	export function channelMessageResponse(content: string) {
322	  return {
323	    type: InteractionCallbackType.CHANNEL_MESSAGE_WITH_SOURCE,
324	    data: { content: content.slice(0, 2000) },
325	  };
326	}
327	
328	/** Extract the single text-input value from a MODAL_SUBMIT interaction payload. */
329	export function extractModalText(interaction: unknown): string {
330	  try {
331	    const data = (interaction as { data?: { components?: unknown[] } }).data;
332	    const row = data?.components?.[0] as { components?: { value?: unknown }[] } | undefined;
333	    const value = row?.components?.[0]?.value;
334	    return typeof value === "string" ? value : "";
335	  } catch {
336	    return "";
337	  }
338	}
339	
340	/**
341	 * Extract the REAL Discord user id of whoever triggered an interaction
342	 * (button click or modal submit), for reply-attribution
343	 * (lib/discord-bridge.ts's `submitDiscordReply`).
344	 *
345	 * This bridge only ever operates inside ONE guild, so a guild interaction's
346	 * `member.user.id` is the field that is actually always present — `user.id`
347	 * (top-level) is Discord's DM-interaction shape and would be undefined here,
348	 * but is checked as a harmless fallback in case that ever changes. Both
349	 * fields are sent and Ed25519-signed by Discord itself (verified by
350	 * `verifyDiscordSignature` BEFORE this is ever called), so once signature
351	 * verification has passed, this id is trustworthy — it cannot be spoofed by
352	 * the Discord user who clicked the button.
353	 */
354	export function extractInteractionUserId(interaction: unknown): string | null {
355	  try {
356	    const i = interaction as { member?: { user?: { id?: unknown } }; user?: { id?: unknown } };
357	    const guildUserId = i.member?.user?.id;
358	    if (typeof guildUserId === "string" && guildUserId) return guildUserId;
359	    const dmUserId = i.user?.id;
360	    if (typeof dmUserId === "string" && dmUserId) return dmUserId;
361	    return null;
362	  } catch {
363	    return null;
364	  }
365	}
