1	import "server-only";
2	import type { Role } from "@prisma/client";
3	import { db } from "./db";
4	import { canAccess } from "./rbac";
5	import {
6	  discordEnabled,
7	  createGuildTextChannel,
8	  postChannelMessage,
9	} from "./discord";
10	import { writeTicketReply, writeChatReply } from "./reply-core";
11	
12	/**
13	 * Nxeon Discord support bridge — Phase 1 (mirror) + the reply round-trip.
14	 *
15	 * SHAPE: one plain text channel per ticket / chat conversation in a single,
16	 * private guild ("Nxeon Cloud"). Text channel, not a forum-with-threads:
17	 * forum channels cannot have PRIVATE threads in Discord's current API, and
18	 * since this whole guild is private anyway, "private within the guild" isn't
19	 * a requirement — a plain channel per ticket is simpler to create/list/delete
20	 * via REST and needs no thread bookkeeping. See lib/discord.ts for the REST
21	 * client and Ed25519 signature verification, and
22	 * app/api/webhooks/discord/route.ts for the Interactions Endpoint that
23	 * handles the Reply button + modal.
24	 *
25	 * ATTRIBUTION (2026-08-30 REWORK — real per-person linking). Every
26	 * Discord-originated reply used to be attributed to a single, hardcoded
27	 * Nxeon User.id (the `discord_reply_as_user_id` setting) — a deliberate
28	 * placeholder for a single-owner-only build. Now that real support staff use
29	 * this bridge too, `submitDiscordReply` resolves the ACTUAL Nxeon staff
30	 * member via `User.discordUserId` — set only through the OAuth linking flow
31	 * in app/api/admin/discord/authorize+callback/route.ts, which a staff member
32	 * completes for themselves from Settings → Integrations. See
33	 * `resolveDiscordReplyActor` below for the exact resolution rule.
34	 *
35	 * DESIGN DECISION: there is NO fallback to the old `discord_reply_as_user_id`
36	 * setting. An unlinked (or since-demoted) Discord account gets a clear,
37	 * visible "link your account" message back in Discord — never a silent
38	 * substitution to some other identity. The entire point of this rework is
39	 * correct PER-PERSON attribution; a quiet fallback to one shared identity
40	 * would partially undo that, and "reject with a clear next step" is a better
41	 * failure mode than "misattribute" for something that lands in an audit trail
42	 * and a customer-facing reply. The cost is real and intentional: the owner's
43	 * own account must also be linked via the new UI before their own replies
44	 * from Discord keep working — see this repo's rollout notes for that step.
45	 *
46	 * ACCESS CONTROL, STILL LAYERED. Discord's own guild membership + invite
47	 * control (who can even see these channels) plus this webhook's Ed25519
48	 * signature verification (nothing reaches this code without both) is the
49	 * outer layer, unchanged. `resolveDiscordReplyActor`'s
50	 * `canAccess(role, "support")` check is what stops a demoted/former staff
51	 * member's still-linked Discord account from continuing to reply as
52	 * themselves after their Nxeon role changes.
53	 *
54	 * KILL-SWITCH DISCIPLINE: every exported function below checks
55	 * `discordEnabled()` FIRST and returns silently if it's off, and every DB/REST
56	 * call is wrapped so a Discord outage or misconfiguration can NEVER throw back
57	 * into a ticket/chat write path — matching this codebase's established
58	 * best-effort third-party-integration pattern (see how `sendMail` failures are
59	 * handled in lib/reply-core.ts).
60	 *
61	 * SCHEMA CAVEAT: `Ticket.discordThreadId` / `ChatConversation.discordThreadId`
62	 * / `User.discordUserId` are NOT YET pushed to the live database (see the doc
63	 * comments on those fields in prisma/schema.prisma) — every read/write of
64	 * them here goes through an explicit `as any`/unchecked cast until a real
65	 * `prisma db push` + `generate` runs for this branch.
66	 */
67	
68	const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
69	
70	// ---------------------------------------------------------------------------
71	// custom_id encoding — shared vocabulary between the message Reply button, the
72	// modal opened in response to it, and the webhook route that parses both.
73	// ---------------------------------------------------------------------------
74	
75	export type BridgeKind = "ticket" | "chat";
76	
77	function isBridgeKind(v: string): v is BridgeKind {
78	  return v === "ticket" || v === "chat";
79	}
80	
81	export function replyButtonCustomId(kind: BridgeKind, id: string): string {
82	  return `dc_reply:${kind}:${id}`;
83	}
84	
85	export function replyModalCustomId(kind: BridgeKind, id: string): string {
86	  return `dc_reply_modal:${kind}:${id}`;
87	}
88	
89	/** Parse a `dc_reply:<kind>:<id>` or `dc_reply_modal:<kind>:<id>` custom_id. */
90	export function parseBridgeCustomId(
91	  customId: string,
92	): { action: "reply" | "reply_modal"; kind: BridgeKind; id: string } | null {
93	  const parts = customId.split(":");
94	  if (parts.length !== 3) return null;
95	  const [prefix, kindRaw, id] = parts;
96	  if (!id) return null;
97	  if (!isBridgeKind(kindRaw)) return null;
98	  if (prefix === "dc_reply") return { action: "reply", kind: kindRaw, id };
99	  if (prefix === "dc_reply_modal") return { action: "reply_modal", kind: kindRaw, id };
100	  return null;
101	}
102	
103	// ---------------------------------------------------------------------------
104	// Ticket mirror
105	// ---------------------------------------------------------------------------
106	
107	type TicketForChannel = { id: string; subject: string; priority: string; userId: string };
108	
109	/** Create the ticket's Discord channel + post the opening context message if
110	 *  it doesn't have one yet; return the (existing or new) channel id. */
111	async function ensureTicketChannel(ticket: TicketForChannel & { discordThreadId?: string | null }): Promise<string | null> {
112	  const existing = (ticket as { discordThreadId?: string | null }).discordThreadId;
113	  if (existing) return existing;
114	
115	  const user = await db.user.findUnique({ where: { id: ticket.userId }, select: { name: true, email: true } });
116	  const channelId = await createGuildTextChannel(
117	    `ticket-${ticket.id.slice(-8)}`,
118	    `Ticket ${ticket.id}: ${ticket.subject}`.slice(0, 1024),
119	  );
120	  if (!channelId) return null;
121	
122	  await postChannelMessage(
123	    channelId,
124	    [
125	      "🎫 **New support ticket**",
126	      `**Subject:** ${ticket.subject}`,
127	      `**Priority:** ${ticket.priority}`,
128	      `**Customer:** ${user?.name ?? "?"}${user?.email ? ` (${user.email})` : ""}`,
129	      `**Admin:** ${APP_URL}/admin/support/${ticket.id}`,
130	    ].join("\n"),
131	  );
132	
133	  await db.ticket.update({ where: { id: ticket.id }, data: { discordThreadId: channelId } as any });
134	  return channelId;
135	}
136	
137	/** Mirror a brand-new ticket (called right after `db.ticket.create`). */
138	export async function mirrorNewTicketToDiscord(ticketId: string): Promise<void> {
139	  if (!(await discordEnabled())) return;
140	  try {
141	    const ticket = await db.ticket.findUnique({
142	      where: { id: ticketId },
143	      include: { messages: { orderBy: { createdAt: "asc" }, take: 1 } },
144	    });
145	    if (!ticket) return;
146	    const channelId = await ensureTicketChannel(ticket);
147	    if (!channelId) return;
148	    const firstMessage = ticket.messages[0];
149	    if (firstMessage) {
150	      await postChannelMessage(channelId, `👤 **Customer:** ${firstMessage.body}`, {
151	        replyButtonCustomId: replyButtonCustomId("ticket", ticket.id),
152	      });
153	    }
154	  } catch (e) {
155	    console.error("[discord-bridge] mirrorNewTicketToDiscord failed (non-fatal)", ticketId, e);
156	  }
157	}
158	
159	/** Mirror a reply on an EXISTING ticket (staff or customer) into its channel,
160	 *  creating the channel first if this ticket predates the bridge (or its
161	 *  earlier mirror attempt failed). */
162	export async function mirrorTicketReplyToDiscord(ticketId: string, body: string, isStaffMessage: boolean): Promise<void> {
163	  if (!(await discordEnabled())) return;
164	  try {
165	    const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
166	    if (!ticket) return;
167	    const channelId = await ensureTicketChannel(ticket);
168	    if (!channelId) return;
169	    const label = isStaffMessage ? "🛟 **Staff**" : "👤 **Customer**";
170	    await postChannelMessage(channelId, `${label}: ${body}`, {
171	      replyButtonCustomId: replyButtonCustomId("ticket", ticketId),
172	    });
173	  } catch (e) {
174	    console.error("[discord-bridge] mirrorTicketReplyToDiscord failed (non-fatal)", ticketId, e);
175	  }
176	}
177	
178	// ---------------------------------------------------------------------------
179	// Chat mirror
180	// ---------------------------------------------------------------------------
181	
182	type ConvoForChannel = { id: string; name: string | null; email: string | null; userId: string | null };
183	
184	async function ensureChatChannel(convo: ConvoForChannel & { discordThreadId?: string | null }): Promise<string | null> {
185	  const existing = (convo as { discordThreadId?: string | null }).discordThreadId;
186	  if (existing) return existing;
187	
188	  const who = convo.name
189	    ? `${convo.name}${convo.email ? ` (${convo.email})` : ""}`
190	    : convo.email || "Anonymous visitor";
191	  const channelId = await createGuildTextChannel(
192	    `chat-${convo.id.slice(-8)}`,
193	    `Live chat ${convo.id}: ${who}`.slice(0, 1024),
194	  );
