213	 *  and "message in an existing conversation" (posts into it) via the same
214	 *  discordThreadId check. The "bot" case covers every message
215	 *  lib/kb-run.ts's AI assistant writes (its own replies, the escalation
216	 *  holding message, the no-agent-available fallback) — full chat history,
217	 *  not just human-authored messages, ends up in Discord. */
218	export async function mirrorChatMessageToDiscord(
219	  conversationId: string,
220	  body: string,
221	  sender: "visitor" | "agent" | "bot",
222	): Promise<void> {
223	  if (!(await discordEnabled())) return;
224	  try {
225	    const convo = await db.chatConversation.findUnique({ where: { id: conversationId } });
226	    if (!convo) return;
