238	// ---------------------------------------------------------------------------
239	// Reply round-trip (Discord → Nxeon) — called by the modal-submit handler in
240	// app/api/webhooks/discord/route.ts. Returns the text to show back in Discord
241	// as the interaction's visible acknowledgement message.
242	// ---------------------------------------------------------------------------
243	
244	const NOT_LINKED_MSG =
245	  `⚠️ Your Discord account isn't linked to a Nxeon staff account (or it no longer has support access). ` +
246	  `Link it at ${APP_URL}/dashboard/settings?tab=integrations to reply from here.`;
247	
248	/**
249	 * The whole "who is this Discord reply attributed to" decision, as a pure
250	 * function of the linked-user lookup — kept separate from the DB call itself
251	 * so it's trivially unit-testable (see test/discord-reply-attribution.test.ts)
252	 * without needing a live database.
253	 *
254	 * `linkedUser` is the result of `User.findUnique({ where: { discordUserId } })`
255	 * (or `null` if there's no `discordUserId` to look up at all — e.g. the
256	 * interaction payload had no resolvable Discord user id). Rejects — rather
257	 * than falling back to anyone — when there's no link OR the linked account no
258	 * longer has support access (e.g. demoted after linking). See this file's
259	 * top-of-file comment for why no fallback exists.
260	 */
261	export function resolveDiscordReplyActor(
262	  linkedUser: { id: string; role: Role } | null,
263	): { actorId: string } | { error: string } {
264	  if (!linkedUser) return { error: NOT_LINKED_MSG };
265	  if (!canAccess(linkedUser.role, "support")) return { error: NOT_LINKED_MSG };
266	  return { actorId: linkedUser.id };
267	}
268	
269	/**
270	 * @param discordUserId The REAL Discord user id of whoever submitted the
271	 *   reply modal (from `extractInteractionUserId` on the verified interaction
272	 *   payload — see app/api/webhooks/discord/route.ts). `null` if it couldn't
273	 *   be extracted, which resolves the same as "not linked".
274	 */
275	export async function submitDiscordReply(
276	  kind: BridgeKind,
277	  id: string,
278	  replyText: string,
279	  discordUserId: string | null,
280	): Promise<string> {
281	  const text = replyText.trim();
282	  if (!text) return "⚠️ Empty reply — nothing sent.";
283	
284	  try {
285	    const linkedUser = discordUserId
286	      ? await db.user.findUnique({ where: { discordUserId } as any, select: { id: true, role: true } })
287	      : null;
288	    const resolved = resolveDiscordReplyActor(linkedUser);
289	    if ("error" in resolved) {
290	      console.error("[discord-bridge] reply rejected — no linked staff account", { kind, id, discordUserId });
291	      return resolved.error;
292	    }
293	    const replyAsUserId = resolved.actorId;
294	
295	    if (kind === "ticket") {
296	      const result = await writeTicketReply({
297	        actorId: replyAsUserId,
298	        actorIsSupportStaff: true,
299	        ticketId: id,
300	        body: text,
301	      });
302	      if (result.error) return `⚠️ ${result.error}`;
303	      return "✅ Reply sent to the customer.";
304	    }
305	
306	    const result = await writeChatReply({ conversationId: id, body: text, staffId: replyAsUserId });
307	    if (result.error) return `⚠️ ${result.error}`;
308	    return "✅ Reply sent to the customer.";
309	  } catch (e) {
310	    console.error("[discord-bridge] submitDiscordReply failed", kind, id, e);
311	    return "⚠️ Something went wrong sending that reply — check the admin panel.";
312	  }
313	}
