3	/**
4	 * Discord OAuth2 (Authorization Code grant, `identify` scope only) for the
5	 * staff Discord-account-linking flow — see
6	 * app/api/admin/discord/authorize/route.ts and
7	 * app/api/admin/discord/callback/route.ts.
8	 *
9	 * This is a SEPARATE credential from the bot token used everywhere else in
10	 * lib/discord.ts: the bot token authenticates the platform's own bot user for
11	 * REST calls (create channel, post message, …); this client id/secret pair
12	 * authenticates the Nxeon Discord APPLICATION to run a normal user-consent
13	 * OAuth flow so a staff member can prove "this Discord account is mine".
14	 * Same Discord application, two different credential types — see Discord's
15	 * own developer portal, which lists both under one app.
16	 *
17	 * Nxeon is a confidential (server-side) client, so this is the plain
18	 * Authorization Code flow with a client secret — no PKCE needed (PKCE exists
19	 * for clients that CAN'T keep a secret; we can). Discord's token endpoint
20	 * accepts client_secret_post (credentials in the form body), which is what's
21	 * used below.
22	 *
23	 * ── STATE / CSRF ─────────────────────────────────────────────────────────
24	 * Rather than stash `state` server-side (a cookie, a DB row) the way
25	 * lib/cloudflare-oauth.ts's flow does, `state` here IS a short-lived signed
26	 * JWT (via `jose`, the same library and secret — AUTH_SECRET — lib/auth.ts's
27	 * session cookie uses) embedding the initiating staff user's id and a
28	 * distinguishing `typ` claim. Discord round-trips `state` verbatim, so:
29	 *   - Signature + expiry verification is real CSRF protection: an attacker
30	 *     cannot forge or replay an old value without AUTH_SECRET.
31	 *   - No server-side storage is needed at all (no cookie to lose across a
32	 *     redirect, no DB row to clean up).
33	 *   - It's a pure, deterministic function — easy to unit test without a
34	 *     cookie jar or DB (see test/discord-oauth-state.test.ts).
35	 * CRITICAL: `state` is CSRF protection ONLY. The callback route re-derives
36	 * the actual signed-in user from the real session (`requireArea("support")`)
37	 * and only uses the state's embedded uid to CONFIRM it matches — never as the
38	 * source of truth for whose account gets linked. See the callback route's
39	 * top-of-file comment.
40	 */
41	
42	import { SignJWT, jwtVerify } from "jose";
43	import { discordApplicationId, discordClientSecret } from "./discord";
44	
45	const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
46	
47	/** Distinguishes this JWT from a session/impersonation token signed with the same secret. */
48	const STATE_TYP = "discord_oauth_state";
49	
50	/** How long a "Connect Discord" attempt has to complete consent. */
51	const STATE_TTL = "10m";
52	
53	const DISCORD_OAUTH_AUTHORIZE_URL = "https://discord.com/oauth2/authorize";
54	const DISCORD_OAUTH_TOKEN_URL = "https://discord.com/api/v10/oauth2/token";
55	const DISCORD_API_USERS_ME = "https://discord.com/api/v10/users/@me";
56	
57	// NOT appUrl()/APP_URL — same reason as the Google Search Console admin OAuth
58	// integration (app/api/admin/integrations/google-search-console/callback/route.ts):
59	// this codebase's session cookie has no explicit Domain attribute (lib/auth.ts),
60	// so it's host-only — a staff member's session on the admin subdomain and any
61	// session on the bare public domain are two completely separate cookie jars.
62	// Found live: an admin who authorized from the admin subdomain landed back on
63	// this callback via the PUBLIC domain, had no staff session there, and got
64	// silently redirected to /dashboard by requireArea("support") with no
65	// indication anything went wrong. Building this off NXEON_ADMIN_ORIGIN instead
66	// keeps the whole flow on the one host staff sessions actually live on.
67	const ADMIN_ORIGIN = () => (process.env.NXEON_ADMIN_ORIGIN ?? "https://nxeon.cloud").replace(/\/$/, "");
68	
69	/** Must exactly match the redirect URI registered on the Discord application. */
70	export function discordOauthRedirectUri(): string {
71	  return `${ADMIN_ORIGIN()}/api/admin/discord/callback`;
72	}
73	
74	// ---------------------------------------------------------------------------
75	// State (CSRF) — sign / verify
76	// ---------------------------------------------------------------------------
77	
78	/** Mint a fresh `state` value bound to the staff user starting the flow. */
79	export async function signDiscordOauthState(uid: string): Promise<string> {
80	  return new SignJWT({ typ: STATE_TYP })
81	    .setProtectedHeader({ alg: "HS256" })
82	    .setSubject(uid)
83	    .setIssuedAt()
84	    .setExpirationTime(STATE_TTL)
85	    .sign(secret);
86	}
87	
88	export type StateCheck = { ok: true } | { ok: false; error: string };
89	
90	/**
91	 * Verify a `state` value round-tripped from Discord. Checks signature,
92	 * expiry, the `typ` claim (so a session/impersonation cookie value can never
93	 * be replayed here even though it shares a secret), AND that the embedded
94	 * uid matches the user CURRENTLY signed in at callback time — binding the
95	 * flow to one continuous session, not just "signed by us at some point".
96	 *
97	 * Never throws — every failure mode (missing, malformed, expired, wrong
98	 * signature, wrong user) returns `{ ok: false, error }` with a message safe
99	 * to show the staff member.
100	 */
101	export async function verifyDiscordOauthState(state: string | null | undefined, expectedUid: string): Promise<StateCheck> {
102	  if (!state) return { ok: false, error: "Missing state — please start the connection again." };
103	  try {
104	    const { payload } = await jwtVerify(state, secret);
105	    if (payload.typ !== STATE_TYP) {
106	      return { ok: false, error: "Invalid state — please start the connection again." };
107	    }
108	    if (payload.sub !== expectedUid) {
109	      return {
110	        ok: false,
111	        error: "This Discord sign-in was started by a different account. Please try again.",
112	      };
113	    }
114	    return { ok: true };
115	  } catch {
116	    // jose throws for a bad signature, malformed token, AND an expired token
117	    // (JWTExpired) — all three collapse to the same user-facing message.
118	    return { ok: false, error: "That Discord sign-in link expired or was tampered with. Please try again." };
119	  }
120	}
121	
122	// ---------------------------------------------------------------------------
123	// Authorization request
124	// ---------------------------------------------------------------------------
125	
126	export async function discordOauthConfigured(): Promise<boolean> {
127	  const [appId, secret] = await Promise.all([discordApplicationId(), discordClientSecret()]);
128	  return Boolean(appId && secret);
129	}
130	
131	/** Build the Discord consent URL for this connection attempt. `identify` is the only scope needed — just the account id + username. */
132	export async function discordAuthorizeUrl(state: string): Promise<string> {
133	  const clientId = await discordApplicationId();
134	  const url = new URL(DISCORD_OAUTH_AUTHORIZE_URL);
135	  url.searchParams.set("client_id", clientId);
136	  url.searchParams.set("redirect_uri", discordOauthRedirectUri());
137	  url.searchParams.set("response_type", "code");
138	  url.searchParams.set("scope", "identify");
139	  url.searchParams.set("state", state);
140	  // Force account chooser every time rather than silently reusing a stale
141	  // Discord session — this is an identity proof, not a "keep me logged in".
142	  url.searchParams.set("prompt", "consent");
143	  return url.toString();
144	}
145	
146	// ---------------------------------------------------------------------------
147	// Token endpoint
148	// ---------------------------------------------------------------------------
149	
150	type TokenResponse = {
151	  access_token?: string;
152	  token_type?: string;
153	  scope?: string;
154	  error?: string;
155	  error_description?: string;
156	};
157	
158	/**
159	 * Exchange an authorization code for an access token. Returns `{ error }`
160	 * (never throws) for a network failure or any error Discord's token endpoint
161	 * reports, so callers can show a friendly message instead of crashing.
162	 */
163	export async function discordExchangeCode(code: string): Promise<{ accessToken?: string; error?: string }> {
164	  const clientId = await discordApplicationId();
165	  const clientSecret = await discordClientSecret();
166	  if (!clientId || !clientSecret) {
167	    return { error: "Discord sign-in isn't fully configured on this server yet." };
168	  }
169	
170	  const params = new URLSearchParams({
171	    client_id: clientId,
172	    client_secret: clientSecret,
173	    grant_type: "authorization_code",
174	    code,
175	    redirect_uri: discordOauthRedirectUri(),
176	  });
177	
178	  let res: Response;
179	  try {
180	    res = await fetch(DISCORD_OAUTH_TOKEN_URL, {
181	      method: "POST",
182	      headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
183	      body: params.toString(),
184	      cache: "no-store",
185	    });
186	  } catch {
187	    return { error: "Couldn't reach Discord to finish connecting. Try again shortly." };
188	  }
189	
190	  let parsed: TokenResponse | null = null;
191	  try {
192	    parsed = (await res.json()) as TokenResponse;
193	  } catch {
194	    parsed = null;
195	  }
196	
197	  if (!res.ok || !parsed?.access_token) {
198	    const detail = parsed?.error_description || parsed?.error || `HTTP ${res.status}`;
199	    return { error: `Discord rejected the connection (${String(detail).slice(0, 160)}).` };
200	  }
201	
202	  return { accessToken: parsed.access_token };
203	}
204	
205	// ---------------------------------------------------------------------------
206	// Identify
207	// ---------------------------------------------------------------------------
208	
209	export type DiscordSelfUser = { id: string; username: string };
210	
211	/** GET /users/@me with the just-obtained access token — the real Discord user id + username. */
212	export async function fetchDiscordSelf(accessToken: string): Promise<{ user?: DiscordSelfUser; error?: string }> {
213	  let res: Response;
214	  try {
215	    res = await fetch(DISCORD_API_USERS_ME, {
216	      headers: { Authorization: `Bearer ${accessToken}` },
217	      cache: "no-store",
218	    });
219	  } catch {
220	    return { error: "Couldn't reach Discord to confirm your account. Try again shortly." };
221	  }
222	  if (!res.ok) {
223	    return { error: `Discord rejected the account lookup (HTTP ${res.status}).` };
224	  }
225	  let json: { id?: unknown; username?: unknown } | null = null;
226	  try {
227	    json = await res.json();
228	  } catch {
229	    json = null;
230	  }
231	  if (!json || typeof json.id !== "string" || !json.id) {
232	    return { error: "Discord didn't return a usable account id." };
233	  }
234	  return { user: { id: json.id, username: typeof json.username === "string" ? json.username : "" } };
235	}
