3	/**
4	 * Staff self-service Discord-account linking — the status query and the
5	 * "Disconnect" action for the Settings → Integrations "Discord account" card
6	 * (components/admin/DiscordIntegration.tsx). The "Connect" side of the flow
7	 * is a plain redirect to app/api/admin/discord/authorize/route.ts (a GET
8	 * route, not a server action, because it has to 302 to Discord).
9	 *
10	 * Every export here is a public network endpoint (see
11	 * lib/actions-support.ts's top-of-file comment on that exact property) — both
12	 * functions re-derive the real signed-in user via `requireArea("support")`
13	 * rather than trusting anything passed in, and neither accepts a userId
14	 * argument. Gated on the "support" area (not just `isStaff`) because that is
15	 * the SAME area lib/actions-chat.ts's `requireArea("support")` gates for
16	 * actually replying to a ticket/chat — a BILLING-role account could link a
17	 * Discord id here, but it would never be usable for a reply (see
18	 * lib/discord-bridge.ts's `resolveDiscordReplyActor`, which re-checks
19	 * `canAccess(role, "support")` independently at reply time). Keeping the
20	 * gates aligned just avoids a pointless "connected but can never use it" UI
21	 * state for BILLING/CUSTOMER accounts.
22	 */
23	
24	import { revalidatePath } from "next/cache";
25	import { db } from "./db";
26	import { requireArea } from "./rbac";
27	import { checkRateLimit } from "./rate-limit";
28	import { getDiscordUserById } from "./discord";
29	import { discordOauthConfigured, discordOauthRedirectUri } from "./discord-oauth";
30	
31	export type DiscordLinkStatus = {
32	  connected: boolean;
33	  /** Best-effort display username — null if unlinked or the lookup failed/was skipped. */
34	  username: string | null;
35	  /** Is "Connect Discord" available in this environment (app id + client secret configured)? */
36	  oauthAvailable: boolean;
37	  /** Shown to an operator when oauthAvailable is false, so they know what to register. */
38	  redirectUri: string;
39	};
40	
41	/** Connection state for the current staff member. Never returns anything sensitive. */
42	export async function getDiscordLinkStatus(): Promise<DiscordLinkStatus> {
43	  const me = await requireArea("support");
44	  const discordUserId = (me as unknown as { discordUserId?: string | null }).discordUserId ?? null;
45	
46	  let username: string | null = null;
47	  if (discordUserId) {
48	    const profile = await getDiscordUserById(discordUserId).catch(() => null);
49	    username = profile?.username || null;
50	  }
51	
52	  return {
53	    connected: Boolean(discordUserId),
54	    username,
55	    oauthAvailable: await discordOauthConfigured(),
56	    redirectUri: discordOauthRedirectUri(),
57	  };
58	}
59	
60	/** Unlink the current staff member's Discord account. Idempotent — fine to call when already unlinked. */
61	export async function disconnectDiscordLink(): Promise<{ ok?: boolean; error?: string }> {
62	  const me = await requireArea("support");
63	
64	  const rl = checkRateLimit(`discord-link-disconnect:${me.id}`, { max: 10, windowMs: 60_000 });
65	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
66	
67	  try {
68	    await db.user.update({ where: { id: me.id }, data: { discordUserId: null } as any });
69	  } catch (e) {
70	    console.error("[discord-link] disconnect failed", me.id, e);
71	    return { error: "Couldn't disconnect Discord right now — try again shortly." };
72	  }
73	  await db.auditLog
74	    .create({ data: { userId: me.id, action: "discord.unlink" } })
75	    .catch(() => {});
76	
77	  revalidatePath("/dashboard/settings");
78	  return { ok: true };
79	}
