24	 * request) never reaches Discord's consent screen: `requireArea` redirects
25	 * to /login or /admin first.
26	 *
27	 * No server-side state storage is needed — `state` is itself a short-lived
28	 * signed JWT (see lib/discord-oauth.ts's top-of-file comment for why that's
29	 * real CSRF protection here).
30	 */
31	export async function GET(_req: NextRequest) {
32	  const me = await requireArea("support");
33	
34	  const rl = checkRateLimit(`discord-oauth-start:${me.id}`, { max: 10, windowMs: 60_000 });
35	  if (!rl.ok) {
36	    return NextResponse.redirect(
37	      `${base()}/dashboard/settings?tab=integrations&discord=error&discordmsg=${encodeURIComponent(
38	        `Too many attempts — try again in ${rl.retryAfterSec}s.`,
39	      )}`,
40	    );
41	  }
42	
43	  if (!(await discordOauthConfigured())) {
44	    return NextResponse.redirect(
45	      `${base()}/dashboard/settings?tab=integrations&discord=error&discordmsg=${encodeURIComponent(
46	        "Discord sign-in isn't set up on this server yet.",
47	      )}`,
48	    );
49	  }
50	
51	  const state = await signDiscordOauthState(me.id);
52	  const authUrl = await discordAuthorizeUrl(state);
53	  return NextResponse.redirect(authUrl);
54	}
