1	import { NextRequest, NextResponse } from "next/server";
2	import { realUser } from "@/lib/auth";
3	import { canAccess, isStaff } from "@/lib/rbac";
4	import { db } from "@/lib/db";
5	import { discordExchangeCode, fetchDiscordSelf, verifyDiscordOauthState } from "@/lib/discord-oauth";
6	
7	export const dynamic = "force-dynamic";
8	
9	// NOT appUrl()/APP_URL — see lib/discord-oauth.ts's discordOauthRedirectUri
10	// doc comment: staff sessions live on the admin subdomain only (host-only
11	// session cookie, no shared Domain attribute). Redirecting back to the public
12	// domain here would land the browser on a page with no valid session at all
13	// (found live: a real admin got silently bounced by requireArea itself, see
14	// the fix below too), matching the established pattern in
15	// app/api/admin/integrations/google-search-console/callback/route.ts.
16	const base = () => (process.env.NXEON_ADMIN_ORIGIN ?? "https://nxeon.cloud").replace(/\/$/, "");
17	
18	const isUniqueConflict = (e: unknown): boolean => (e as { code?: string } | null)?.code === "P2002";
19	
20	function redirectWith(params: Record<string, string>): NextResponse {
21	  const url = new URL(`${base()}/dashboard/settings`);
22	  url.searchParams.set("tab", "integrations");
23	  for (const [k, v] of Object.entries(params)) url.searchParams.set(k, v);
24	  return NextResponse.redirect(url.toString());
25	}
26	
27	function fail(msg: string): NextResponse {
28	  return redirectWith({ discord: "error", discordmsg: msg });
29	}
30	
31	/**
32	 * Step 2 of "Connect Discord": the OAuth redirect target. MUST live at
33	 * exactly `/api/admin/discord/callback` — that path is registered verbatim
34	 * as the redirect URI on the Discord application.
35	 *
36	 * IDENTITY, NOT JUST CSRF. Two separate things happen here and they must not
37	 * be conflated:
38	 *   1. `state` is checked (`verifyDiscordOauthState`) purely as CSRF
39	 *      protection — proof this callback corresponds to a request THIS
40	 *      server actually issued, recently, for the currently-signed-in user.
41	 *   2. The Nxeon identity that gets `discordUserId` written onto it is
42	 *      `requireArea("support")`'s return value — the REAL session, re-derived
43	 *      independently at callback time. Nothing about WHOSE account gets
44	 *      linked ever comes from the OAuth round-trip (the `code`, `state`, or
45	 *      anything Discord sends) — only Discord's own `/users/@me` response
46	 *      (after we independently obtained the access token with our own
47	 *      client secret) supplies the Discord-side id being linked.
48	 * Do not "simplify" this by trusting an id embedded in `state` for anything
49	 * beyond the equality check inside `verifyDiscordOauthState`.
50	 */
51	export async function GET(req: NextRequest) {
52	  // Not requireArea("support") here on purpose: that helper's own guard
53	  // redirects to /login or /dashboard directly the instant a check fails,
54	  // bypassing this route's fail()/redirectWith() entirely — which is exactly
55	  // how a real admin got silently bounced to their dashboard with zero
56	  // explanation when their session on THIS origin wasn't valid (see the
57	  // domain fix above this route, and lib/discord-oauth.ts's doc comment).
58	  // Same two checks requireArea makes, same order, real error message.
59	  const me = await realUser();
60	  if (!me) {
61	    return fail("You're not signed in on this origin — sign in again and retry from Settings → Integrations.");
62	  }
63	  if (!isStaff(me.role) || !canAccess(me.role, "support")) {
64	    return fail("Your account doesn't have support access, so it can't be linked to the Discord bridge.");
65	  }
66	
67	  const sp = req.nextUrl.searchParams;
68	
69	  // The staff member declined on Discord's consent screen (or Discord errored).
70	  const oauthError = sp.get("error");
71	  if (oauthError) {
72	    return fail(
73	      oauthError === "access_denied"
74	        ? "Discord connection cancelled."
75	        : `Discord returned an error (${oauthError.slice(0, 60)}).`,
76	    );
77	  }
78	
79	  const state = sp.get("state");
80	  const stateCheck = await verifyDiscordOauthState(state, me.id);
81	  if (!stateCheck.ok) return fail(stateCheck.error);
82	
83	  const code = sp.get("code");
84	  if (!code) return fail("Discord didn't return an authorization code. Please try connecting again.");
85	
86	  const exchanged = await discordExchangeCode(code);
87	  if (!exchanged.accessToken) {
88	    return fail(exchanged.error ?? "Couldn't complete the Discord connection. Please try again.");
89	  }
90	
91	  const identified = await fetchDiscordSelf(exchanged.accessToken);
92	  if (!identified.user) {
93	    return fail(identified.error ?? "Couldn't confirm your Discord account. Please try again.");
94	  }
95	
96	  try {
97	    await db.user.update({
98	      where: { id: me.id },
99	      data: { discordUserId: identified.user.id } as any,
100	    });
101	  } catch (e) {
102	    if (isUniqueConflict(e)) {
103	      return fail("This Discord account is already linked to another Nxeon staff account.");
104	    }
105	    console.error("[discord-oauth] failed to store discordUserId for", me.id, e);
106	    return fail("Couldn't save the Discord connection right now. Please try again shortly.");
107	  }
108	
109	  await db.auditLog
110	    .create({ data: { userId: me.id, action: "discord.link", detail: identified.user.username || identified.user.id } })
111	    .catch(() => {});
112	
113	  return redirectWith({ discord: "connected" });
114	}
