1	import { NextResponse } from "next/server";
2	import {
3	  discordPublicKey,
4	  verifyDiscordSignature,
5	  InteractionType,
6	  replyModalResponse,
7	  channelMessageResponse,
8	  extractModalText,
9	  extractInteractionUserId,
10	} from "@/lib/discord";
11	import { parseBridgeCustomId, replyModalCustomId, submitDiscordReply } from "@/lib/discord-bridge";
12	
13	export const runtime = "nodejs";
14	
15	/**
16	 * Discord "Interactions Endpoint" webhook — the reply half of the support
17	 * bridge (see lib/discord-bridge.ts's top-of-file comment for the full
18	 * picture). Handles exactly three interaction shapes:
19	 *
20	 *   1. PING (type 1)              → PONG. Discord requires this before it will
21	 *                                    even save this URL in the Developer
22	 *                                    Portal, and it periodically re-sends PINGs
23	 *                                    (plus deliberately-invalid signatures) to
24	 *                                    keep testing the endpoint.
25	 *   2. MESSAGE_COMPONENT (type 3) → the "Reply" button under a mirrored
26	 *                                    message. Responds by opening a MODAL
27	 *                                    (type 9) — Discord requires the modal to
28	 *                                    be opened as the DIRECT response to the
29	 *                                    button click, not a follow-up call.
30	 *   3. MODAL_SUBMIT (type 5)      → the reply text a staff member typed.
31	 *                                    Resolves WHO they are via
32	 *                                    `interaction.member.user.id` (the real,
33	 *                                    Discord-signed id of whoever submitted
34	 *                                    it) against `User.discordUserId` — see
35	 *                                    lib/discord-bridge.ts's
36	 *                                    `resolveDiscordReplyActor` — then writes
37	 *                                    through the shared reply-writing core
38	 *                                    (lib/reply-core.ts) and acknowledges with
39	 *                                    a visible confirmation/error message.
40	 *
41	 * Signature verification mirrors app/api/stripe/webhook/route.ts's pattern:
42	 * read the RAW body as text before any JSON parsing, verify a signature
43	 * header (Ed25519 here, HMAC there), and reject with a 4xx on any failure —
44	 * this is SECURITY CRITICAL. Every other interaction shape (slash commands,
45	 * autocomplete, …) is currently unused and gets a generic ack rather than an
46	 * error, since Discord expects SOME response.
47	 */
48	export async function POST(req: Request) {
49	  const rawBody = await req.text();
50	  const signature = req.headers.get("X-Signature-Ed25519");
51	  const timestamp = req.headers.get("X-Signature-Timestamp");
52	  const publicKeyHex = await discordPublicKey();
53	
54	  if (!publicKeyHex) {
55	    console.error("[discord-webhook] no discord_public_key configured — rejecting");
56	    return NextResponse.json({ error: "not configured" }, { status: 401 });
57	  }
58	
59	  const valid = verifyDiscordSignature({ rawBody, signature, timestamp, publicKeyHex });
60	  if (!valid) {
61	    return NextResponse.json({ error: "invalid request signature" }, { status: 401 });
62	  }
63	
64	  let interaction: Record<string, unknown>;
65	  try {
66	    interaction = JSON.parse(rawBody);
67	  } catch {
68	    return NextResponse.json({ error: "invalid body" }, { status: 400 });
69	  }
70	
71	  const type = interaction.type as number | undefined;
72	
73	  // 1. PING — must be answered exactly like this or Discord refuses to save
74	  // the endpoint URL in the Developer Portal.
75	  if (type === InteractionType.PING) {
76	    return NextResponse.json({ type: 1 });
77	  }
78	
79	  // 2. Button click ("Reply") — open the reply modal.
80	  if (type === InteractionType.MESSAGE_COMPONENT) {
81	    const customId = (interaction.data as { custom_id?: string } | undefined)?.custom_id ?? "";
82	    const parsed = parseBridgeCustomId(customId);
83	    if (!parsed || parsed.action !== "reply") {
84	      return NextResponse.json(channelMessageResponse("Unrecognized button."));
85	    }
86	    return NextResponse.json(replyModalResponse(replyModalCustomId(parsed.kind, parsed.id)));
87	  }
88	
89	  // 3. Modal submit — the owner's typed reply.
90	  if (type === InteractionType.MODAL_SUBMIT) {
91	    const customId = (interaction.data as { custom_id?: string } | undefined)?.custom_id ?? "";
92	    const parsed = parseBridgeCustomId(customId);
93	    if (!parsed || parsed.action !== "reply_modal") {
94	      return NextResponse.json(channelMessageResponse("Unrecognized submission."));
95	    }
96	    const text = extractModalText(interaction);
97	    const discordUserId = extractInteractionUserId(interaction);
98	    const ackText = await submitDiscordReply(parsed.kind, parsed.id, text, discordUserId);
99	    return NextResponse.json(channelMessageResponse(ackText));
100	  }
101	
102	  // Any other interaction type (slash commands, autocomplete, …): none are
103	  // registered by this bridge, but Discord still expects a response.
104	  return NextResponse.json(channelMessageResponse("This interaction isn't handled."));
105	}
