7	/**
8	 * Settings → Integrations "Discord account" card — staff-only self-service
9	 * linking for the Discord support bridge's reply-attribution
10	 * (lib/discord-bridge.ts's `resolveDiscordReplyActor`). Only rendered for
11	 * staff roles (see app/dashboard/settings/page.tsx) — a CUSTOMER-role user
12	 * would hit a redirect from the authorize route even if this somehow rendered
13	 * for them, but there's no reason to show it to them at all.
14	 */
15	export function DiscordIntegration({
16	  connected: initialConnected,
17	  username: initialUsername,
18	  oauthAvailable,
19	  redirectUri,
20	}: {
21	  connected: boolean;
22	  username: string | null;
23	  oauthAvailable: boolean;
24	  redirectUri: string;
25	}) {
26	  const [connected, setConnected] = useState(initialConnected);
27	  const [username, setUsername] = useState(initialUsername);
28	  const [error, setError] = useState<string | null>(null);
29	  const [status, setStatus] = useState<string | null>(null);
30	  const [pending, start] = useTransition();
31	
32	  // Read the one-shot ?discord=connected|error&discordmsg=… flags the OAuth
33	  // callback redirects back with, then scrub them from the address bar so a
34	  // refresh doesn't re-show the banner.
35	  useEffect(() => {
36	    const sp = new URLSearchParams(window.location.search);
37	    const result = sp.get("discord");
38	    const msg = sp.get("discordmsg");
39	    if (!result) return;
40	
41	    if (result === "connected") {
42	      setConnected(true);
43	      setStatus("Discord connected. Replies you send from Discord will now be attributed to you.");
44	    } else if (result === "error") {
45	      setError(msg || "Couldn't connect Discord.");
46	    }
47	
48	    ["discord", "discordmsg"].forEach((k) => sp.delete(k));
49	    const qs = sp.toString();
50	    window.history.replaceState({}, "", `${window.location.pathname}${qs ? `?${qs}` : ""}`);
51	  }, []);
52	
53	  function disconnect() {
54	    setError(null);
55	    setStatus(null);
56	    start(async () => {
57	      const res = await disconnectDiscordLink();
58	      if (res?.error) setError(res.error);
59	      else {
60	        setConnected(false);
61	        setUsername(null);
62	        setStatus("Discord disconnected. Replies from Discord will no longer be attributed to you until you reconnect.");
63	      }
64	    });
65	  }
66	
67	  return (
68	    <div className="card">
69	      <div className="mb-1 flex flex-wrap items-center justify-between gap-2">
70	        <h2 className="font-semibold">Discord account</h2>
71	        {connected ? (
72	          <Badge tone="green">Connected{username ? ` as ${username}` : ""}</Badge>
73	        ) : (
74	          <Badge tone="slate">Not connected</Badge>
75	        )}
76	      </div>
77	
78	      <p className="mb-4 text-sm text-slate-400">
79	        Link your Discord account so replies you send from the support bridge (clicking Reply on a
80	        mirrored ticket or chat message) are correctly attributed to you, not to a shared identity.
81	        We only ask to confirm your Discord account id and username — we never post as you or read
82	        your Discord messages.
83	      </p>
84	
85	      {error && (
86	        <div className="mb-3 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
87	          {error}
88	        </div>
89	      )}
90	      {status && (
91	        <div className="mb-3 rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
92	          {status}
93	        </div>
94	      )}
95	
96	      {connected ? (
97	        <div className="flex flex-wrap items-center gap-3">
98	          <button className="btn-secondary py-1.5 text-sm" onClick={disconnect} disabled={pending}>
99	            {pending ? "Disconnecting…" : "Disconnect Discord"}
100	          </button>
101	          <span className="text-xs text-slate-500">
102	            You won&apos;t be able to reply from Discord until you reconnect.
103	          </span>
104	        </div>
105	      ) : oauthAvailable ? (
106	        <a href="/api/admin/discord/authorize" className="btn-secondary inline-block py-1.5 text-sm">
107	          Connect Discord
108	        </a>
109	      ) : (
110	        <p className="text-[11px] text-slate-600">
111	          Operator note: set the <span className="font-mono">discord_client_secret</span> setting
112	          (encrypted, same as <span className="font-mono">discord_bot_token</span>) and confirm{" "}
113	          <span className="font-mono">{redirectUri}</span> is registered as an OAuth2 redirect on the
114	          Discord application, to enable one-click connect.
115	        </p>
116	      )}
117	    </div>
118	  );
119	}
